package com.xiangjiaojiaozhu.englishclock;
import android.content.*;import android.graphics.*;import android.net.*;import com.google.android.gms.tasks.Tasks;import com.google.mlkit.vision.common.*;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.latin.*;import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;import com.tom_roush.pdfbox.pdmodel.*;import com.tom_roush.pdfbox.rendering.*;import com.tom_roush.pdfbox.text.*;import java.io.*;import java.util.zip.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public class ImportUtil{
 static String read(Context c,Uri u,String m)throws Exception{String n=name(c,u).toLowerCase();if(n.endsWith(".pdf"))return pdf(c,u);if(n.endsWith(".docx"))return docx(c,u);return stream(c.getContentResolver().openInputStream(u));}static String stream(InputStream i)throws Exception{BufferedReader b=new BufferedReader(new InputStreamReader(i));StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l).append('\n');b.close();return s.toString();}static String name(Context c,Uri u){Cursor q=c.getContentResolver().query(u,null,null,null,null);try{if(q!=null&&q.moveToFirst()){int i=q.getColumnIndex("_display_name");if(i>=0)return q.getString(i);}}finally{if(q!=null)q.close();}return"article.txt";}
 static String docx(Context c,Uri u)throws Exception{ZipInputStream z=new ZipInputStream(c.getContentResolver().openInputStream(u));ZipEntry e;while((e=z.getNextEntry())!=null)if(e.getName().equals("word/document.xml")){Document d=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(z);NodeList p=d.getElementsByTagName("w:p");StringBuilder o=new StringBuilder();for(int i=0;i<p.getLength();i++){walk(p.item(i).getChildNodes(),o);o.append("\n\n");}z.close();return o.toString();}throw new Exception("DOCX 没有正文");}static void walk(NodeList n,StringBuilder o){for(int i=0;i<n.getLength();i++){Node x=n.item(i);if("w:t".equals(x.getNodeName()))o.append(x.getTextContent());walk(x.getChildNodes(),o);}}
 static String pdf(Context c,Uri u)throws Exception{PDFBoxResourceLoader.init(c);File f=File.createTempFile("ec","pdf",c.getCacheDir());InputStream in=c.getContentResolver().openInputStream(u);FileOutputStream out=new FileOutputStream(f);byte[]q=new byte[8192];int n;while((n=in.read(q))>0)out.write(q,0,n);in.close();out.close();PDDocument d=PDDocument.load(f);String t=new PDFTextStripper().getText(d);if(t.replaceAll("[^A-Za-z]","").length()<30){PDFRenderer r=new PDFRenderer(d);TextRecognizer rec=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);StringBuilder s=new StringBuilder();for(int p=0;p<d.getNumberOfPages();p++){Bitmap b=r.renderImageWithDPI(p,220);Text x=Tasks.await(rec.process(InputImage.fromBitmap(b,0)));s.append(x.getText()).append("\n\n");b.recycle();}rec.close();t=s.toString();}d.close();f.delete();return t;}
}
